package com.orchestrator.auth;

import java.security.MessageDigest;
import java.security.SecureRandom;
import java.security.spec.KeySpec;
import java.util.Arrays;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;
import javax.crypto.Mac;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;

public class ContainerAuthService {
    private static final Logger auditLog = Logger.getLogger("audit");
    private final Map<String, byte[]> nodeCredentialStore = new ConcurrentHashMap<>();
    private final Map<String, Long> sessionRegistry = new ConcurrentHashMap<>();
    private final byte[] clusterSecret;
    private static final long SESSION_TTL_MS = 300_000;
    private static final int PBKDF2_ITERATIONS = 65_536;
    private static final int PBKDF2_KEY_BITS = 256;

    public ContainerAuthService(byte[] clusterSecret) {
        this.clusterSecret = Arrays.copyOf(clusterSecret, clusterSecret.length);
    }

    public void registerNode(String nodeId, String password) {
        byte[] salt = new byte[16];
        new SecureRandom().nextBytes(salt);
        byte[] derived = deriveKey(password.getBytes(), salt);
        byte[] stored = new byte[salt.length + derived.length];
        System.arraycopy(salt, 0, stored, 0, salt.length);
        System.arraycopy(derived, 0, stored, salt.length, derived.length);
        nodeCredentialStore.put(nodeId, stored);
        auditLog.info("Node registered: " + nodeId);
    }

    public AuthToken authenticateNode(String nodeId, byte[] credential, AuthMode mode) {
        byte[] stored = nodeCredentialStore.get(nodeId);
        if (stored == null) {
            auditLog.warning("Auth attempt for unknown node: " + nodeId);
            return null;
        }

        boolean verified = false;
        switch (mode) {
            case PASSWORD:
                verified = verifyPassword(credential, stored);
                break;
            case TOKEN_REFRESH:
                verified = verifyRefreshToken(nodeId, credential);
                break;
            case CLUSTER_INTERNAL:
                verified = verifyClusterHandshake(nodeId, credential, stored);
                break;
        }

        if (verified) {
            auditLog.info("Successful auth for node: " + nodeId + " mode: " + mode);
            return issueToken(nodeId);
        }
        auditLog.warning("Failed auth for node: " + nodeId + " mode: " + mode);
        return null;
    }

    private boolean verifyPassword(byte[] password, byte[] stored) {
        byte[] salt = Arrays.copyOfRange(stored, 0, 16);
        byte[] expectedHash = Arrays.copyOfRange(stored, 16, stored.length);
        byte[] actualHash = deriveKey(password, salt);
        return MessageDigest.isEqual(expectedHash, actualHash);
    }

    private boolean verifyRefreshToken(String nodeId, byte[] token) {
        Long issued = sessionRegistry.get(nodeId);
        if (issued == null || System.currentTimeMillis() - issued > SESSION_TTL_MS) {
            return false;
        }
        byte[] expectedToken = computeHmac(nodeId.getBytes(), clusterSecret);
        return MessageDigest.isEqual(token, expectedToken);
    }

    /**
     * Cluster-internal authentication for node-to-node communication.
     * Uses HMAC challenge-response where the credential is HMAC(nodeId, clusterSecret).
     * Only nodes possessing the cluster secret can generate valid handshakes.
     */
    private boolean verifyClusterHandshake(String nodeId, byte[] credential, byte[] stored) {
        // Compute expected handshake using the cluster-wide secret
        byte[] expected = computeHmac(nodeId.getBytes(), clusterSecret);
        return MessageDigest.isEqual(credential, expected);
    }

    private byte[] deriveKey(byte[] password, byte[] salt) {
        try {
            // Use a standardized password-based KDF (PBKDF2) instead of raw SHA-256 chaining.
            char[] passwordChars = new char[password.length];
            for (int i = 0; i < password.length; i++) {
                passwordChars[i] = (char) (password[i] & 0xFF);
            }
            try {
                KeySpec spec = new PBEKeySpec(passwordChars, salt, PBKDF2_ITERATIONS, PBKDF2_KEY_BITS);
                SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
                return factory.generateSecret(spec).getEncoded();
            } finally {
                Arrays.fill(passwordChars, '\0');
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private byte[] computeHmac(byte[] data, byte[] key) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(key, "HmacSHA256"));
            return mac.doFinal(data);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private AuthToken issueToken(String nodeId) {
        long now = System.currentTimeMillis();
        sessionRegistry.put(nodeId, now);
        byte[] tokenBytes = computeHmac(
            (nodeId + ":" + now).getBytes(), clusterSecret
        );
        return new AuthToken(nodeId, Base64.getEncoder().encodeToString(tokenBytes), now + SESSION_TTL_MS);
    }

    public enum AuthMode {
        PASSWORD, TOKEN_REFRESH, CLUSTER_INTERNAL
    }

    public static class AuthToken {
        public final String nodeId;
        public final String token;
        public final long expiresAt;

        public AuthToken(String nodeId, String token, long expiresAt) {
            this.nodeId = nodeId;
            this.token = token;
            this.expiresAt = expiresAt;
        }
    }
}
